style.css:
@-moz-document domain("roblox.com") {
/* ================================================= */
/* GLOBAL */
/* ================================================= */

body {
    background: #ffffff !important;
    font-family: Arial, sans-serif !important;
    color: #000 !important;
}

/* REMOVE ROUNDED CORNERS */

* {
    border-radius: 0px !important;
    backdrop-filter: none !important;
    box-shadow: none !important;
}

/* ================================================= */
/* CLASSIC HEADER */
/* ================================================= */

.rbx-header,
#header {
    background: linear-gradient(#3d6db5, #24508f) !important;
    border-bottom: 2px solid #16345f !important;
    height: 70px !important;
}

/* OLD ROBLOX LOGO */

.rbx-navbar-header::before {
    content: "";
    display: block;
    width: 220px;
    height: 60px;
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/2/23/Roblox_2006_logo.svg");
    background-size: contain;
    background-repeat: no-repeat;
    margin-top: 5px;
}

/* Hide modern logo */
.rbx-navbar-header img,
.rbx-navbar-icon {
    opacity: 0 !important;
}

/* ================================================= */
/* OLD GREEN PLAY BUTTON */
/* ================================================= */

.btn-common-play-game-lg,
.btn-primary-md,
.btn-primary-lg {

    background: linear-gradient(#49d14d, #1f9e25) !important;
    border: 1px solid #17791b !important;
    color: white !important;
    font-weight: bold !important;
    text-shadow: 1px 1px #116614 !important;
}

.btn-common-play-game-lg:hover {
    background: linear-gradient(#5be45f, #27b52d) !important;
}

/* ================================================= */
/* OLD BOX STYLE */
/* ================================================= */

.card,
.game-card,
.section,
.container-header,
.list-item {

    background: #f2f2f2 !important;
    border: 1px solid #b6b6b6 !important;
}

/* ================================================= */
/* LINKS */
/* ================================================= */

a {
    color: #114da8 !important;
}

a:hover {
    color: #d10000 !important;
    text-decoration: underline !important;
}

/* ================================================= */
/* CLASSIC LOGIN PAGE */
/* ================================================= */

.login-page,
.login-container {

    background: url("https://tr.rbxcdn.com/8d3f8b6db2b3b0f65f5ec52ffb62a1cb/768/432/Image/Png") center top no-repeat !important;

    background-size: cover !important;
}

/* ================================================= */
/* OLD ROBLOX ADS */
/* ================================================= */

/* Fake nostalgic ad */

.game-main-content::before {

    content: "";
    display: block;

    width: 728px;
    height: 90px;

    margin: 10px auto;

    background-image: url("https://i.imgur.com/UYiroys.png");

    background-size: cover;

    border: 1px solid #888;
}

/* Side ad */

.game-main-content::after {

    content: "";

    display: block;

    width: 160px;
    height: 600px;

    position: fixed;

    right: 10px;
    top: 120px;

    background-image: url("https://i.imgur.com/twBQ8G5.png");

    background-size: cover;

    border: 1px solid #777;

    z-index: 999;
}

/* ================================================= */
/* REMOVE MODERN EFFECTS */
/* ================================================= */

.game-card:hover,
.card:hover {
    transform: none !important;
}

/* ================================================= */
/* OLD SEARCH BAR */
/* ================================================= */

input {
    border: 1px solid #7f9db9 !important;
    background: white !important;
}

/* ================================================= */
/* OLD SIDEBAR */
/* ================================================= */

.left-col,
.nav,
.rbx-left-col {

    background: #ececec !important;
    border-right: 1px solid #b6b6b6 !important;
}

/* ================================================= */
/* CLASSIC THUMBNAILS */
/* ================================================= */

img {
    image-rendering: auto !important;
}

/* ================================================= */
/* OLD BUTTONS */
/* ================================================= */

button {

    background: linear-gradient(#f4f4f4, #d7d7d7) !important;

    border: 1px solid #999 !important;

    color: black !important;
}

/* ================================================= */
/* REMOVE MODERN DARK UI */
/* ================================================= */

.dark-theme,
[data-theme="dark"] {
    filter: brightness(1.1) !important;
}
}
